package fraymus.workspace;

import org.json.*;
import java.util.*;

/** Auditable local data computation. No physics actuation, inference provider or executable cells. */
final class MotionData {
    static final String PROCEDURE="motion-data-report-v1";
    private MotionData(){}
    static void criteria(double gap,double speed){RampDefinition.range(gap,.000001,86400,"maximum time gap");RampDefinition.range(speed,.000001,1e9,"speed quality threshold");}
    static JSONObject binding(JSONObject data){return new JSONObject().put("datasetId",data.getString("datasetId")).put("datasetVersion",data.getInt("version")).put("title",data.getString("title")).put("sourceSha256",data.getString("sourceSha256")).put("mappingSha256",data.getString("mappingSha256")).put("versionSha256",MeasurementStore.hash(data.toString())).put("sourceKind",data.getString("sourceKind"));}
    static JSONArray originalRows(JSONObject data){
        String csv=data.getString("csv");if(!MeasurementStore.hash(csv).equals(data.getString("sourceSha256")))throw new IllegalStateException("Original CSV hash changed");
        var m=data.getJSONObject("mapping");String tu=m.getString("timeUnit"),du=m.getString("distanceUnit"),missing=data.getString("missingPolicy");
        double ts=switch(tu){case "s"->1;case "ms"->.001;default->throw new IllegalArgumentException("Unknown time unit");},ds=switch(du){case "m"->1;case "cm"->.01;case "mm"->.001;default->throw new IllegalArgumentException("Unknown distance unit");};
        double offset=m.getDouble("timeOffsetS"),origin=m.getDouble("distanceOrigin"),direction=m.getDouble("direction");
        var identity=new JSONArray(List.of(data.getString("sourceSha256"),m.getString("timeColumn"),m.getString("distanceColumn"),tu,du,offset,origin,direction,missing));if(!MeasurementStore.hash(identity.toString()).equals(data.getString("mappingSha256")))throw new IllegalStateException("Frozen mapping hash changed");
        var raw=MeasurementStore.csv(csv);var headers=raw.getFirst().stream().map(String::strip).toList();int ti=headers.indexOf(m.getString("timeColumn")),di=headers.indexOf(m.getString("distanceColumn"));if(ti<0||di<0||ti==di)throw new IllegalStateException("Frozen columns no longer exist");
        var rows=new JSONArray();var skipped=new JSONArray();double previous=-1;
        for(int i=1;i<raw.size();i++){var row=raw.get(i);if(row.size()!=headers.size())throw new IllegalStateException("CSV row width changed");if(row.get(ti).isBlank()||row.get(di).isBlank()){if(!missing.equals("skip"))throw new IllegalStateException("Missing source value");skipped.put(i+1);continue;}
            double t=MeasurementStore.cellNumber(row.get(ti),i+1)*ts+offset,x=(MeasurementStore.cellNumber(row.get(di),i+1)-origin)*ds*direction;
            if(!Double.isFinite(t)||!Double.isFinite(x)||t<0||t>86400||t<=previous||Math.abs(x)>1e6)throw new IllegalStateException("Invalid reconstructed source row");previous=t;rows.put(new JSONObject().put("sourceRow",i+1).put("timeS",t).put("distanceM",x));
        }
        if(rows.length()<2||!rows.similar(data.getJSONArray("rows"))||!skipped.similar(data.getJSONArray("skippedRows")))throw new IllegalStateException("Normalized rows differ from original CSV and mapping");return rows;
    }
    static JSONObject analyze(JSONObject data,double maxGap,double speedLimit){
        criteria(maxGap,speedLimit);var rows=originalRows(data);var intervals=new JSONArray();var acceleration=new JSONArray();var flags=new JSONArray();double travel=0,peak=0,largestGap=0,peakAcceleration=0;int gaps=0,speeds=0;
        for(int i=1;i<rows.length();i++){
            var a=rows.getJSONObject(i-1);var b=rows.getJSONObject(i);double dt=b.getDouble("timeS")-a.getDouble("timeS"),dx=b.getDouble("distanceM")-a.getDouble("distanceM"),v=finite(dx/dt),mid=a.getDouble("timeS")+dt/2;
            var segment=new JSONObject().put("index",i).put("sourceFrom",a.getInt("sourceRow")).put("sourceTo",b.getInt("sourceRow")).put("startS",a.getDouble("timeS")).put("endS",b.getDouble("timeS")).put("midS",mid).put("deltaS",dt).put("deltaM",dx).put("velocityMps",v);intervals.put(segment);travel+=Math.abs(dx);peak=Math.max(peak,Math.abs(v));largestGap=Math.max(largestGap,dt);
            if(dt>maxGap){gaps++;flags.put(new JSONObject().put("interval",i).put("kind","time-gap").put("actual",dt).put("limit",maxGap));}if(Math.abs(v)>speedLimit){speeds++;flags.put(new JSONObject().put("interval",i).put("kind","speed").put("actual",Math.abs(v)).put("limit",speedLimit));}
            if(i>1){var p=intervals.getJSONObject(i-2);double delta=mid-p.getDouble("midS"),value=finite((v-p.getDouble("velocityMps"))/delta);peakAcceleration=Math.max(peakAcceleration,Math.abs(value));acceleration.put(new JSONObject().put("betweenIntervals",i-1).put("timeS",p.getDouble("midS")+delta/2).put("accelerationMps2",value));}
        }
        var first=rows.getJSONObject(0);var last=rows.getJSONObject(rows.length()-1);double duration=last.getDouble("timeS")-first.getDouble("timeS"),net=last.getDouble("distanceM")-first.getDouble("distanceM");int skipped=data.getJSONArray("skippedRows").length();
        var summary=new JSONObject().put("rowCount",rows.length()).put("intervalCount",intervals.length()).put("durationS",duration).put("netDisplacementM",net).put("totalTravelM",travel).put("meanVelocityMps",finite(net/duration)).put("meanSpeedMps",finite(travel/duration)).put("peakAbsVelocityMps",peak).put("maxGapS",largestGap).put("peakAbsAccelerationMps2",acceleration.isEmpty()?JSONObject.NULL:peakAcceleration).put("gapFlags",gaps).put("speedFlags",speeds).put("skippedSourceRows",skipped).put("qualityPassed",gaps==0&&speeds==0&&skipped==0).put("passed",true);
        // Different checks reconstruct integrated displacement/travel from the derived intervals.
        double integrated=0,absolute=0;for(Object raw:intervals){var s=(JSONObject)raw;integrated+=s.getDouble("velocityMps")*s.getDouble("deltaS");absolute+=Math.abs(s.getDouble("velocityMps"))*s.getDouble("deltaS");}close(integrated,net);close(absolute,travel);
        return new JSONObject().put("method","motion-data-v1: explicit SI mapping, adjacent-segment velocities, acceleration between segment midpoints; no smoothing or model fit").put("source",binding(data)).put("criteria",new JSONObject().put("maxGapS",maxGap).put("speedLimitMps",speedLimit)).put("rows",rows).put("intervals",intervals).put("accelerations",acceleration).put("flags",flags).put("summary",summary);
    }
    private static double finite(double v){if(!Double.isFinite(v))throw new IllegalArgumentException("Derived motion exceeds finite numerical range; check mapped time spacing and units");return v;}
    private static void close(double a,double b){if(Math.abs(a-b)>1e-10*Math.max(1,Math.max(Math.abs(a),Math.abs(b))))throw new IllegalStateException("Motion integration invariant failed");}
    static JSONArray checks(JSONObject g){var a=g.getJSONObject("analysis");var s=a.getJSONObject("summary");return new JSONArray()
        .put(new JSONObject().put("selector","#verdict").put("expectText","Data analysis verified"))
        .put(new JSONObject().put("selector","#goal-id").put("expectText",g.getString("id")))
        .put(new JSONObject().put("selector","#source-hash").put("expectText",g.getJSONObject("dataBinding").getString("sourceSha256")))
        .put(new JSONObject().put("selector","#data-rows tr").put("expectCount",s.getInt("rowCount")))
        .put(new JSONObject().put("selector","#position .data-series").put("expectCount",1))
        .put(new JSONObject().put("selector","#velocity .data-series").put("expectCount",1))
        .put(new JSONObject().put("selector","#quality").put("expectText",s.getBoolean("qualityPassed")?"Within declared quality thresholds":"Quality flags found"))
        .put(new JSONObject().put("selector","#scope").put("expectText","Derived from source data. Source labels are user supplied; this is not causal physics or hardware validation."));}
    static JSONObject report(JSONObject g,JSONObject data){
        var a=g.getJSONObject("analysis");var s=a.getJSONObject("summary");var rows=a.getJSONArray("rows");var intervals=a.getJSONArray("intervals");var table=new StringBuilder();var csv=new StringBuilder("source_row,time_s,displacement_m\n");
        for(Object raw:rows){var p=(JSONObject)raw;table.append("<tr><td>").append(p.getInt("sourceRow")).append("</td><td>").append(n(p.getDouble("timeS"))).append("</td><td>").append(n(p.getDouble("distanceM"))).append("</td></tr>");csv.append(p.getInt("sourceRow")).append(',').append(p.getDouble("timeS")).append(',').append(p.getDouble("distanceM")).append('\n');}
        String quality=s.getBoolean("qualityPassed")?"Within declared quality thresholds":"Quality flags found";
        String html="<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Verified motion data</title><style>body{background:#eef3f2;color:#173b35;font:16px/1.5 system-ui;margin:0}main{max-width:1000px;margin:auto;padding:28px}section{background:white;border:1px solid #b8cbc4;border-radius:14px;padding:20px;margin:18px 0}.metrics{display:flex;gap:24px;flex-wrap:wrap}.metrics b{display:block;font-size:26px}svg{width:100%;background:#f9fbfa}svg text{font:13px system-ui;fill:#31584e}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:7px;text-align:left;border-bottom:1px solid #dbe5df}code{overflow-wrap:anywhere}small{color:#5b7169}h1{font-size:32px}</style><main><p>FRAYNIX / OFFLINE DATA PROCEDURE / EDITION 020</p><h1 id='verdict'>Data analysis verified</h1><p>"+escape(data.getString("title"))+" · dataset v"+data.getInt("version")+" · "+escape(data.getString("sourceKind"))+" (user supplied)</p><section class='metrics'><div><b>"+s.getInt("rowCount")+"</b>Mapped samples</div><div><b>"+n(s.getDouble("totalTravelM"))+" m</b>Total travel</div><div><b>"+n(s.getDouble("meanSpeedMps"))+" m/s</b>Mean speed</div></section><section>"+chart("position",rows,"timeS","distanceM","Mapped displacement (m)",false)+chart("velocity",intervals,"midS","velocityMps","Derived segment velocity (m/s)",true)+"<p>Velocity is a finite difference over each interval, displayed at its midpoint. Acceleration is a difference between adjacent interval velocities. No smoothing, invented samples or physical model fit.</p></section><section><h2 id='quality'>"+quality+"</h2><p>Time gaps: "+s.getInt("gapFlags")+" · speed flags: "+s.getInt("speedFlags")+" · source rows explicitly skipped: "+s.getInt("skippedSourceRows")+".</p><p>Declared gap limit: "+n(g.getDouble("maxGapS"))+" s · speed threshold: "+n(g.getDouble("speedLimitMps"))+" m/s. A verified report may correctly flag low-quality data.</p><p id='scope'>Derived from source data. Source labels are user supplied; this is not causal physics or hardware validation.</p><p>Source SHA-256 <code id='source-hash'>"+data.getString("sourceSha256")+"</code><br>Mapping SHA-256 <code>"+data.getString("mappingSha256")+"</code><br>Goal <code id='goal-id'>"+g.getString("id")+"</code></p><p>Source note: "+escape(data.getString("sourceNote"))+"</p><details><summary>Mapped source rows</summary><table><thead><tr><th>CSV row</th><th>Time s</th><th>Displacement m</th></tr></thead><tbody id='data-rows'>"+table+"</tbody></table></details></section></main></html>";
        var files=new JSONObject().put("index.html",html).put("original.csv",data.getString("csv")).put("normalized.csv",csv.toString()).put("normalized.json",rows.toString()).put("intervals.json",intervals.toString()).put("accelerations.json",a.getJSONArray("accelerations").toString()).put("quality.json",a.getJSONArray("flags").toString()).put("summary.json",new JSONObject().put("summary",s).put("source",a.getJSONObject("source")).put("mapping",data.getJSONObject("mapping")).put("filename",data.getString("filename")).put("sourceNote",data.getString("sourceNote")).put("sourceLabelUserSupplied",true).put("skippedSourceRowNumbers",data.getJSONArray("skippedRows")).put("criteria",a.getJSONObject("criteria")).put("method",a.getString("method")).toString(2));
        return new JSONObject().put("title","Motion data · "+g.getString("id").substring(0,8)).put("files",files).put("sources",new JSONArray(List.of("goal:"+g.getString("id"),"dataset:"+data.getString("datasetId")+":v"+data.getInt("version"),"sha256:"+data.getString("sourceSha256"))));
    }
    private static String chart(String id,JSONArray rows,String xKey,String yKey,String label,boolean symmetric){
        double first=rows.getJSONObject(0).getDouble(xKey),last=rows.getJSONObject(rows.length()-1).getDouble(xKey),lo=0,hi=0;for(Object raw:rows){double v=((JSONObject)raw).getDouble(yKey);lo=Math.min(lo,v);hi=Math.max(hi,v);}double scale=Math.max(1e-12,Math.max(Math.abs(lo),Math.abs(hi)));var points=new StringBuilder();double singleY=0;
        for(Object raw:rows){var p=(JSONObject)raw;double x=last==first?400:40+720*(p.getDouble(xKey)-first)/(last-first),y=symmetric?140-110*(p.getDouble(yKey)/scale):260-230*((p.getDouble(yKey)/scale-lo/scale)/Math.max(1e-12,hi/scale-lo/scale));singleY=y;points.append(String.format(Locale.ROOT,"%.3f,%.3f ",x,y));}
        return "<svg id='"+id+"' viewBox='0 0 800 300' role='img' aria-label='"+label+"'><path d='M40 30V260H760' fill='none' stroke='#7c958b'/><text x='45' y='20'>"+label+" · range "+n(symmetric?-scale:lo)+" to "+n(symmetric?scale:hi)+"</text><polyline class='data-series' fill='none' stroke='"+(symmetric?"#9660b8":"#247a60")+"' stroke-width='2.5' points='"+points+"'/>"+(rows.length()==1?"<circle cx='400' cy='"+singleY+"' r='4' fill='#9660b8'/>":"")+"<text x='40' y='285'>"+n(first)+" s</text><text x='660' y='285'>"+n(last)+" s</text></svg>";
    }
    private static String n(double v){return String.format(Locale.ROOT,"%.6g",v);}
    private static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
}
